const msg = $json.body.entry?.[0]?.changes?.[0]?.value?.messages?.[0];
if (!msg) return [];
const contact = $json.body.entry[0].changes[0].value.contacts?.[0] || {};
const media = msg.image || msg.document || null;
const texto = msg.text?.body || msg.caption || media?.caption || '';
// Heurística de ruteo: es SOLICITUD si es texto (sin adjunto) y menciona pago + datos de transporte
const t = texto.toUpperCase();
const esSolicitud = !media && (
  (t.includes('PAGO') || t.includes('PAGAR')) &&
  (t.includes('CUENTA DE COBRO') || t.includes('REMISION') || t.includes('REMISIÓN') || t.includes('TRANSPORT') || t.includes('CEDULA') || t.includes('CÉDULA'))
);
let idCompraRef = null;
if (!media && !esSolicitud) {
  const m = t.match(/\b(?:ID|COMPRA|COTIZACION|COTIZACIÓN)\s*[:#.]?\s*(\d{4,6})\b/) || t.match(/^\s*(\d{4,6})\s*$/);
  if (m) idCompraRef = parseInt(m[1]);
}
return [{ json: {
  ruta: media ? 'COMPROBANTE' : (esSolicitud ? 'SOLICITUD_TRANSPORTE' : (idCompraRef ? 'REFERENCIA_ID' : 'IGNORAR')),
  id_compra_ref: idCompraRef,
  wa_from: msg.from,
  wa_name: contact.profile?.name || '',
  wa_msg_id: msg.id,
  wa_timestamp: new Date(parseInt(msg.timestamp) * 1000).toISOString(),
  texto,
  media_id: media?.id || null,
  mime_type: media?.mime_type || null,
  filename: media?.filename || (media ? 'comprobante_' + msg.id + (media.mime_type === 'application/pdf' ? '.pdf' : '.jpg') : null)
}}];

// IMPORTANTE: este nodo recibe su entrada DIRECTO del nodo de descarga (con binario).
// 'Subir a Google Drive' corre en rama paralela; 'Parsear resultado OCR' lee su salida por referencia.
const b64 = Buffer.from(await this.helpers.getBinaryDataBuffer(0, 'data')).toString('base64');
const mime = $('Clasificar mensaje (adjunto vs solicitud)').first().json.mime_type;
const isPdf = mime === 'application/pdf';
const block = isPdf
  ? { type: 'document', source: { type: 'base64', media_type: 'application/pdf', data: b64 } }
  : { type: 'image', source: { type: 'base64', media_type: mime, data: b64 } };
return [{ json: { anthropic_body: {
  model: 'claude-sonnet-4-6', max_tokens: 1024,
  messages: [{ role: 'user', content: [ block, { type: 'text', text: `Eres el sistema OCR contable de MeUp (Colombia). Analiza este documento y responde SOLO con JSON válido, sin markdown, con esta estructura:
{
 "clasificacion": "COMPROBANTE_PAGO|FACTURA|EXTRACTO|OTRO",
 "direccion": "RECIBIDO|ENVIADO|DESCONOCIDO",
 "fecha_pago": "YYYY-MM-DD o null",
 "valor": numero o null,
 "moneda": "COP|USD",
 "banco_origen": "string o null",
 "banco_destino": "string o null",
 "medio": "NEQUI|DAVIPLATA|BANCOLOMBIA|PSE|OTRO",
 "referencia": "string o null",
 "nombre_pagador": "string o null",
 "nombre_destinatario": "string o null",
 "telefono_destino": "string o null",
 "destino_es_meup": true|false|null,
 "origen_es_meup": true|false|null,
 "confianza": "ALTA|MEDIA|BAJA",
 "observaciones": "string"
}
CUENTAS E IDENTIFICADORES DE MEUP (la empresa receptora): nombre contiene MEUP o ME UP; NIT 900570024; cuentas Bancolombia corriente terminada en 3762, Bancolombia ahorros 8985, Davivienda ahorros 4335, Davivienda corriente 6614, Banco Agrario 9030, Bancolombia Panamá 3826.
REGLAS:
- destino_es_meup = true si el beneficiario/cuenta destino coincide con los identificadores de MeUp; false si claramente es otra persona/empresa; null si no se ve.
- origen_es_meup = igual pero para el pagador/cuenta origen.
- Un cliente pagando a MeUp genera un pantallazo donde el dinero SALE de su cuenta HACIA MeUp: eso es destino_es_meup=true (es un INGRESO para MeUp aunque diga 'Enviaste').
- punto = separador de miles (700.000 = 700000).
- En Nequi/Daviplata el teléfono destino suele ser visible: extráelo en telefono_destino.` } ] }]
}}}];

let p = { clasificacion: 'OTRO', confianza: 'BAJA', observaciones: 'Error de parseo OCR' };
try {
  const raw = $json.content.filter(b => b.type === 'text').map(b => b.text).join('');
  p = JSON.parse(raw.replace(/```json|```/g, '').trim());
} catch (e) {}
const meta = $('Clasificar mensaje (adjunto vs solicitud)').first().json;
const drive = $('Subir a Google Drive').first().json;
// Clasificación por FLUJO DE DINERO respecto a MeUp (no por la dirección del pantallazo):
// destino = MeUp → ingreso de cliente; origen = MeUp → egreso; ambiguo → pista del caption; default = pago de cliente.
let clasif = p.clasificacion;
if (p.clasificacion === 'COMPROBANTE_PAGO') {
  const cap = (meta.texto || '').toUpperCase();
  if (p.destino_es_meup === true) clasif = 'COMPROBANTE_PAGO';
  else if (p.origen_es_meup === true && p.destino_es_meup !== true) clasif = 'COMPROBANTE_EGRESO';
  else if (/TRANSPORTISTA|FLETE|CUENTA DE COBRO|REMISION|REMISIÓN/.test(cap)) clasif = 'COMPROBANTE_EGRESO';
  else clasif = 'COMPROBANTE_PAGO';
}
const esEgreso = clasif === 'COMPROBANTE_EGRESO';
return [{ json: {
  ID_DOC: 'WA-' + Date.now().toString().slice(-9),
  FECHA_RECIBIDO: meta.wa_timestamp.replace('T',' ').slice(0,16),
  REMITENTE_WA: '+' + meta.wa_from,
  NOMBRE_CONTACTO: meta.wa_name,
  TIPO_ARCHIVO: meta.mime_type,
  URL_DRIVE: drive.webViewLink || ('https://drive.google.com/file/d/' + drive.id),
  OCR_ESTADO: p.confianza === 'BAJA' ? 'REVISAR' : 'OK',
  OCR_FECHA_PAGO: p.fecha_pago || '',
  OCR_VALOR: p.valor || '',
  OCR_BANCO_ORIGEN: p.banco_origen || '',
  OCR_BANCO_DESTINO: (p.banco_destino || p.medio || ''),
  OCR_REFERENCIA: [p.referencia, p.telefono_destino].filter(Boolean).join(' | '),
  OCR_CLIENTE: esEgreso ? (p.nombre_destinatario || '') : (p.nombre_pagador || ''),
  OCR_CONFIANZA: p.confianza,
  CLASIFICACION: clasif,
  ID_MOV_MATCH: '',
  ESTADO: p.clasificacion === 'COMPROBANTE_PAGO' ? 'PROCESADO' : 'REVISAR',
  RECIBO_SIIGO: '',
  NOTAS: (p.observaciones || '') + (meta.texto ? ' | Caption: ' + meta.texto : ''),
  HUMAN_REVIEW: 'PENDIENTE'
}}];

// Busca el comprobante MÁS RECIENTE del mismo remitente (ventana de 60 min) y le asigna la ID de compra
const meta = $('Clasificar mensaje (adjunto vs solicitud)').first().json;
const filas = $('Leer comprobantes recientes').all().map(i => i.json);
const remitente = 'tg:' + meta.wa_from;
const ahora = new Date(meta.wa_timestamp).getTime();
const candidatas = filas
  .filter(f => f.REMITENTE_WA === remitente && f.FECHA_RECIBIDO)
  .map(f => ({ f, ts: new Date(String(f.FECHA_RECIBIDO).replace(' ', 'T')).getTime() }))
  .filter(x => !isNaN(x.ts) && (ahora - x.ts) >= 0 && (ahora - x.ts) <= 60 * 60 * 1000)
  .sort((a, b) => b.ts - a.ts);
if (candidatas.length === 0) {
  return [{ json: { encontrado: false, id_compra: meta.id_compra_ref, remitente, aviso: 'Llegó la referencia de compra ' + meta.id_compra_ref + ' pero no hay comprobante de ' + (meta.wa_name || remitente) + ' en la última hora.' } }];
}
const c = candidatas[0].f;
return [{ json: { encontrado: true, ID_DOC: c.ID_DOC, id_compra: meta.id_compra_ref, nombre: meta.wa_name,
  notas_nuevas: ((c.NOTAS || '') + ' | ID compra informada por asesor: ' + meta.id_compra_ref).slice(0, 500) } }];
